import axios from 'axios';

const instance = axios.create({
  baseURL: process.env.REACT_APP_SERVER_URL,
  withCredentials: true, // Đảm bảo gửi cookie cùng với request
});

// Lấy access token từ localStorage
const getAccessToken = () => {
  const tokenRaw = window.localStorage.getItem('persist:auth');
  if (!tokenRaw) return null;

  try {
    const parsed = JSON.parse(tokenRaw);
    const userData = parsed.user ? JSON.parse(parsed.user) : null;
    return userData?.token || null;
  } catch (err) {
    console.error('Error parsing token from localStorage:', err);
    return null;
  }
};

// Thêm access token vào header của mỗi request
instance.interceptors.request.use(
  (config) => {
    const token = getAccessToken();
    if (token) {
      config.headers['Authorization'] = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Biến để theo dõi trạng thái refresh token
let isRefreshing = false;
let refreshSubscribers = [];

// Hàm đăng ký callback khi refresh token thành công
const subscribeTokenRefresh = (cb) => {
  refreshSubscribers.push(cb);
};

// Hàm thông báo cho các callback khi refresh token hoàn tất
const onTokenRefreshed = () => {
  refreshSubscribers.map((cb) => cb());
  refreshSubscribers = [];
};

instance.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;
    if (
      error.response?.status === 401 &&
      !originalRequest._retry &&
      !originalRequest.url.includes('/refresh-token')
    ) {
      originalRequest._retry = true;

      if (!isRefreshing) {
        isRefreshing = true;
        try {
          const refreshResponse = await axios.post(
            `${process.env.REACT_APP_SERVER_URL}/api/user/refreshtoken`,
            {},
            { withCredentials: true }
          );

          const newAccessToken = refreshResponse.data.token;
          const persistAuth = window.localStorage.getItem('persist:auth');
          if (persistAuth) {
            const parsed = JSON.parse(persistAuth);
            const user = parsed.user ? JSON.parse(parsed.user) : null;

            const updated = {
              ...parsed,
              user: JSON.stringify({
                ...user,
                token: newAccessToken,
              }),
            };
            window.localStorage.setItem('persist:auth', JSON.stringify(updated));
          }

          originalRequest.headers['Authorization'] = `Bearer ${newAccessToken}`;

          return instance(originalRequest);
        } catch (refreshError) {
          window.localStorage.clear();
          window.location.href = '/';
          return Promise.reject(refreshError);
        } finally {
          isRefreshing = false;
          onTokenRefreshed();
        }
      }

      return new Promise((resolve) => {
        subscribeTokenRefresh(() => {
          originalRequest.headers['Authorization'] = `Bearer ${getAccessToken()}`;
          resolve(instance(originalRequest));
        });
      });
    }

    return Promise.reject(error);
  }
);

export default instance;
